/**
 * Rocky planet surface shader.
 *
 * Produces a smooth rocky sphere with two lit zones (highlight / shadow)
 * separated by dithered borders. Used as the base layer for the rocky,
 * islands, and lava planet types.
 *
 * Dithering: a checker pattern aligned to the pixel grid creates a half-tone
 * transition band at each light border. This gives the characteristic
 * pixel-art dithering look without a true ordered dither matrix.
 *
 * Port of NoAtmosphere.gdshader.
 */
export declare const ROCK_FRAG_SRC = "#version 300 es\nprecision mediump float;\n\nuniform float pixels;\nuniform float rotation;\nuniform vec2  light_origin;\nuniform float time_speed;\nuniform float dither_size;\nuniform float light_border_1;\nuniform float light_border_2;\nuniform vec4  colors[3];\nuniform float size;\nuniform int   OCTAVES;\nuniform float seed;\nuniform float time;\nuniform int   should_dither;\nuniform float uv_offset;   // remap for oversized canvas (0 when canvasScale=1)\nuniform float uv_scale;    // = 1/(2*planetR) (1 when canvasScale=1)\nin  vec2 UV;\nlayout(location=0) out vec4 fragColor;\n\nfloat rand(vec2 coord) {\n  coord = mod(coord, vec2(1.0) * round(size));\n  return fract(sin(dot(coord.xy, vec2(12.9898, 78.233))) * 15.5453 * seed);\n}\nfloat noise(vec2 coord) {\n  vec2 i = floor(coord), f = fract(coord);\n  float a = rand(i), b = rand(i+vec2(1,0)), c = rand(i+vec2(0,1)), d = rand(i+vec2(1,1));\n  vec2 u = f*f*(3.0-2.0*f);\n  return mix(a,b,u.x)+(c-a)*u.y*(1.0-u.x)+(d-b)*u.x*u.y;\n}\nfloat fbm(vec2 coord) {\n  float v=0.0,s=0.5;\n  for(int i=0;i<OCTAVES;i++){v+=noise(coord)*s;coord*=2.0;s*=0.5;}\n  return v;\n}\nbool dither(vec2 uv1, vec2 uv2) {\n  return mod(uv1.x + uv2.y, 2.0/pixels) <= 1.0/pixels;\n}\nvec2 rotate(vec2 coord, float angle) {\n  coord -= 0.5;\n  coord *= mat2(vec2(cos(angle),-sin(angle)), vec2(sin(angle),cos(angle)));\n  return coord + 0.5;\n}\n// Surface height at a disc-space point \u2014 the same field that drives the colour\n// bands, sampled so we can derive terrain relief (highs and lows) from it.\nfloat terrainHeight(vec2 p) {\n  p = rotate(p, rotation);\n  float f = fbm(p);\n  return fbm(p * size + f + vec2(time * time_speed, 0.0));\n}\nvoid main() {\n  vec2 uv_raw = floor(UV * pixels) / pixels;\n  vec2 uv = (uv_raw - uv_offset) * uv_scale;\n  float d_circle = distance(uv, vec2(0.5));\n  float d_light  = distance(uv, light_origin);\n  float a = step(d_circle, 0.49999);\n  bool dith = dither(uv, UV);\n  vec2 puv = uv;                       // disc-space, pre-rotate (for relief)\n  uv = rotate(uv, rotation);\n  float fbm1 = fbm(uv);\n  d_light += fbm(uv * size + fbm1 + vec2(time * time_speed, 0.0)) * 0.3;\n  float dither_border = (1.0/pixels) * dither_size;\n  vec4 col = colors[0];\n  if (d_light > light_border_1) {\n    col = colors[1];\n    if (d_light < light_border_1 + dither_border && (dith || should_dither == 0)) col = colors[0];\n  }\n  if (d_light > light_border_2) {\n    col = colors[2];\n    if (d_light < light_border_2 + dither_border && (dith || should_dither == 0)) col = colors[1];\n  }\n  // Ground relief: hillshade the height field so slopes facing the light read\n  // as highs (brighter) and shaded slopes as lows (darker). Directional\n  // derivative along the light vector, posterized into chunky pixel-art steps.\n  vec2 ld = normalize(light_origin - vec2(0.5) + 1e-5);\n  float e = 1.6 / pixels;\n  float relief = terrainHeight(puv - ld * e) - terrainHeight(puv + ld * e);\n  relief = clamp(relief * 3.4, -0.5, 0.5);\n  relief = floor(relief * 3.0 + 0.5) / 3.0;\n  col.rgb *= 1.0 + relief * 0.7;\n  fragColor = vec4(col.rgb, a * col.a);\n}";
